import { formatDate } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import {
  FormBuilder,
  FormControl,
  FormGroup,
  Validators,
} from '@angular/forms';
import { Router } from '@angular/router';
import { HeaderMenusService } from 'src/app/Services/header-menus.service';
import { SharedService } from 'src/app/Services/shared.service';
import { UserService } from 'src/app/Services/user.service';
import { HeaderMenus } from '../../Models/header-menus.dto';
import { UserDTO } from '../../Models/user.dto';

type RegisterFormModel = {
  name: FormControl<string>;
  surname_1: FormControl<string>;
  surname_2: FormControl<string>;
  alias: FormControl<string>;
  birth_date: FormControl<string>;
  email: FormControl<string>;
  password: FormControl<string>;
};

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.scss'],
})
export class RegisterComponent implements OnInit {
  // TODO 16
  registerUser: UserDTO;

  name: FormControl<string>;
  surname_1: FormControl<string>;
  surname_2: FormControl<string>;
  alias: FormControl<string>;
  birth_date: FormControl<string>;
  email: FormControl<string>;
  password: FormControl<string>;

  registerForm: FormGroup<RegisterFormModel>;
  isValidForm: boolean | null;

  constructor(
    private formBuilder: FormBuilder,
    private userService: UserService,
    private sharedService: SharedService,
    private headerMenusService: HeaderMenusService,
    private router: Router,
  ) {
    // TODO 17

    this.registerUser = new UserDTO('', '', '', '', new Date(), '', '');
    this.isValidForm = null;

    this.name = new FormControl(this.registerUser.name, {
      nonNullable: true,
      validators: [
        Validators.required,
        Validators.minLength(5),
        Validators.maxLength(25),
      ],
    });

    this.surname_1 = new FormControl(this.registerUser.surname_1, {
      nonNullable: true,
      validators: [
        Validators.required,
        Validators.minLength(5),
        Validators.maxLength(25),
      ],
    });

    this.surname_2 = new FormControl(this.registerUser.surname_2 ?? '', {
      nonNullable: true,
      validators: [Validators.minLength(5), Validators.maxLength(25)],
    });

    this.alias = new FormControl(this.registerUser.alias, {
      nonNullable: true,
      validators: [
        Validators.required,
        Validators.minLength(5),
        Validators.maxLength(25),
      ],
    });

    this.birth_date = new FormControl(
      formatDate(new Date(), 'yyyy-MM-dd', 'en'),
      {
        nonNullable: true,
        validators: [Validators.required],
      },
    );

    this.email = new FormControl(this.registerUser.email, {
      nonNullable: true,
      validators: [Validators.required, Validators.email],
    });

    this.password = new FormControl(this.registerUser.password, {
      nonNullable: true,
      validators: [
        Validators.required,
        Validators.minLength(8),
        Validators.maxLength(16),
      ],
    });

    this.registerForm = this.formBuilder.group({
      name: this.name,
      surname_1: this.surname_1,
      surname_2: this.surname_2,
      alias: this.alias,
      birth_date: this.birth_date,
      email: this.email,
      password: this.password,
    });
  }

  ngOnInit(): void {}

  async register(): Promise<void> {
    let responseOK = false;
    this.isValidForm = false;
    let errorResponse: any;

    if (this.registerForm.invalid) {
      return;
    }

    this.isValidForm = true;

    const raw = this.registerForm.getRawValue();

    // Convertir birth_date (string yyyy-MM-dd) a Date
    const birthDate = new Date(raw.birth_date);

    // surname_2: si viene vacío, pasamos string vacío para cumplir constructor
    const surname2 = raw.surname_2 ?? '';

    this.registerUser = new UserDTO(
      raw.name,
      raw.surname_1,
      surname2,
      raw.alias,
      birthDate,
      raw.email,
      raw.password,
    );

    try {
      await this.userService.register(this.registerUser);
      responseOK = true;
    } catch (error: any) {
      responseOK = false;
      errorResponse = error.error;

      const headerInfo: HeaderMenus = {
        showAuthSection: false,
        showNoAuthSection: true,
      };
      this.headerMenusService.headerManagement.next(headerInfo);

      this.sharedService.errorLog(errorResponse);
    }

    await this.sharedService.managementToast(
      'registerFeedback',
      responseOK,
      errorResponse,
    );

    if (responseOK) {
      this.registerForm.reset();

      // Volver a setear el birth_date por defecto
      this.birth_date.setValue(formatDate(new Date(), 'yyyy-MM-dd', 'en'));

      this.router.navigateByUrl('home');
    }
  }
}
<div style="margin-left: auto; margin-right: auto">
  <p id="registerFeedback"></p>
</div>
<div>
  <h1>Register</h1>

  <!-- TODO 18 -->
  <form *ngIf="registerForm" [formGroup]="registerForm" (ngSubmit)="register()">
    <div>
      <label for="name">Name:</label>
      <input id="name" type="text" [formControl]="name" />

      <div *ngIf="name.errors">
        <div
          *ngIf="name.errors && isValidForm != null && !isValidForm"
          [ngClass]="'error'"
        >
          <div *ngIf="name.errors.required">Name is required</div>
          <div *ngIf="name.errors.minlength">
            Name must be at least 5 characters long.
          </div>
          <div *ngIf="name.errors.maxlength">
            Name can be max 25 characters long.
          </div>
        </div>
      </div>
    </div>

    <div>
      <label for="surname_1">Surname 1:</label>
      <input id="surname_1" type="text" [formControl]="surname_1" />

      <div *ngIf="surname_1.errors">
        <div
          *ngIf="surname_1.errors && isValidForm != null && !isValidForm"
          [ngClass]="'error'"
        >
          <div *ngIf="surname_1.errors.required">Surname 1 is required</div>
          <div *ngIf="surname_1.errors.minlength">
            Surname 1 must be at least 5 characters long.
          </div>
          <div *ngIf="surname_1.errors.maxlength">
            Surname 1 can be max 25 characters long.
          </div>
        </div>
      </div>
    </div>

    <div>
      <label for="surname_2">Surname 2:</label>
      <input id="surname_2" type="text" [formControl]="surname_2" />

      <div *ngIf="surname_2.errors">
        <div
          *ngIf="surname_2.errors && isValidForm != null && !isValidForm"
          [ngClass]="'error'"
        >
          <div *ngIf="surname_2.errors.minlength">
            Surname 2 must be at least 5 characters long.
          </div>
          <div *ngIf="surname_2.errors.maxlength">
            Surname 2 can be max 25 characters long.
          </div>
        </div>
      </div>
    </div>

    <div>
      <label for="alias">Alias:</label>
      <input id="alias" type="text" [formControl]="alias" />

      <div *ngIf="alias.errors">
        <div
          *ngIf="alias.errors && isValidForm != null && !isValidForm"
          [ngClass]="'error'"
        >
          <div *ngIf="alias.errors.required">Alias is required</div>
          <div *ngIf="alias.errors.minlength">
            Alias must be at least 5 characters long.
          </div>
          <div *ngIf="alias.errors.maxlength">
            Alias can be max 25 characters long.
          </div>
        </div>
      </div>
    </div>

    <div>
      <label for="birth_date">Birth date:</label>
      <input id="birth_date" type="date" [formControl]="birth_date" />

      <div *ngIf="birth_date.errors">
        <div
          *ngIf="birth_date.errors && isValidForm != null && !isValidForm"
          [ngClass]="'error'"
        >
          <div *ngIf="birth_date.errors.required">Birth date is required</div>
        </div>
      </div>
    </div>

    <div>
      <label for="email">Email:</label>
      <input id="email" type="email" [formControl]="email" />

      <div *ngIf="email.errors">
        <div
          *ngIf="email.errors && isValidForm != null && !isValidForm"
          [ngClass]="'error'"
        >
          <div *ngIf="email.errors.required">Email is required</div>
          <div *ngIf="email.errors.email">Email format is invalid</div>
        </div>
      </div>
    </div>

    <div>
      <label for="password">Password:</label>
      <input id="password" type="password" [formControl]="password" />

      <div *ngIf="password.errors">
        <div
          *ngIf="password.errors && isValidForm != null && !isValidForm"
          [ngClass]="'error'"
        >
          <div *ngIf="password.errors.required">Password is required</div>
          <div *ngIf="password.errors.minlength">
            Password must be at least 8 characters long.
          </div>
          <div *ngIf="password.errors.maxlength">
            Password can be max 16 characters long.
          </div>
        </div>
      </div>
    </div>

    <button type="submit">REGISTER</button>
  </form>
</div>
